/* Generated from neo-brutalism.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='neo-brutalism'],
[data-ui-theme='neo-brutalism'] {
  color-scheme: light;
  --ui-background: oklch(1.00 0 0);
  --ui-foreground: oklch(0 0 0);
  --ui-card: oklch(1.00 0 0);
  --ui-card-foreground: oklch(0 0 0);
  --ui-popover: oklch(1.00 0 0);
  --ui-popover-foreground: oklch(0 0 0);
  --ui-primary: oklch(0.65 0.24 26.97);
  --ui-primary-foreground: oklch(1.00 0 0);
  --ui-secondary: oklch(0.97 0.21 109.77);
  --ui-secondary-foreground: oklch(0 0 0);
  --ui-muted: oklch(0.96 0 0);
  --ui-muted-foreground: oklch(0.32 0 0);
  --ui-accent: oklch(0.56 0.24 260.82);
  --ui-accent-foreground: oklch(1.00 0 0);
  --ui-destructive: oklch(0 0 0);
  --ui-destructive-foreground: oklch(1.00 0 0);
  --ui-border: oklch(0 0 0);
  --ui-input: oklch(0 0 0);
  --ui-ring: oklch(0.65 0.24 26.97);
  --ui-chart-1: oklch(0.65 0.24 26.97);
  --ui-chart-2: oklch(0.97 0.21 109.77);
  --ui-chart-3: oklch(0.56 0.24 260.82);
  --ui-chart-4: oklch(0.73 0.25 142.50);
  --ui-chart-5: oklch(0.59 0.27 328.36);
  --ui-sidebar: oklch(0.96 0 0);
  --ui-sidebar-foreground: oklch(0 0 0);
  --ui-sidebar-primary: oklch(0.65 0.24 26.97);
  --ui-sidebar-primary-foreground: oklch(1.00 0 0);
  --ui-sidebar-accent: oklch(0.56 0.24 260.82);
  --ui-sidebar-accent-foreground: oklch(1.00 0 0);
  --ui-sidebar-border: oklch(0 0 0);
  --ui-sidebar-ring: oklch(0.65 0.24 26.97);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Space Mono', ui-serif, serif;
  --ui-font-heading: 'DM Sans', ui-sans-serif, sans-serif;
  --ui-font-mono: 'Space Mono', ui-monospace, monospace;
  --ui-shadow-control: 4px 4px 0px 0px oklch(0.00 0 0 / 0.50);
  --ui-shadow-panel:
    4px 4px 0px 0px oklch(0.00 0 0 / 1.00), 4px 4px 6px -1px oklch(0.00 0 0 / 1.00);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='neo-brutalism'].dark,
[data-ui-theme='neo-brutalism'].dark {
  color-scheme: dark;
  --ui-background: oklch(0 0 0);
  --ui-foreground: oklch(1.00 0 0);
  --ui-card: oklch(0.32 0 0);
  --ui-card-foreground: oklch(1.00 0 0);
  --ui-popover: oklch(0.32 0 0);
  --ui-popover-foreground: oklch(1.00 0 0);
  --ui-primary: oklch(0.70 0.19 23.19);
  --ui-primary-foreground: oklch(0 0 0);
  --ui-secondary: oklch(0.97 0.20 109.62);
  --ui-secondary-foreground: oklch(0 0 0);
  --ui-muted: oklch(0.32 0 0);
  --ui-muted-foreground: oklch(0.85 0 0);
  --ui-accent: oklch(0.68 0.18 252.26);
  --ui-accent-foreground: oklch(0 0 0);
  --ui-destructive: oklch(1.00 0 0);
  --ui-destructive-foreground: oklch(0 0 0);
  --ui-border: oklch(1.00 0 0);
  --ui-input: oklch(1.00 0 0);
  --ui-ring: oklch(0.70 0.19 23.19);
  --ui-chart-1: oklch(0.70 0.19 23.19);
  --ui-chart-2: oklch(0.97 0.20 109.62);
  --ui-chart-3: oklch(0.68 0.18 252.26);
  --ui-chart-4: oklch(0.74 0.23 142.85);
  --ui-chart-5: oklch(0.61 0.25 328.07);
  --ui-sidebar: oklch(0 0 0);
  --ui-sidebar-foreground: oklch(1.00 0 0);
  --ui-sidebar-primary: oklch(0.70 0.19 23.19);
  --ui-sidebar-primary-foreground: oklch(0 0 0);
  --ui-sidebar-accent: oklch(0.68 0.18 252.26);
  --ui-sidebar-accent-foreground: oklch(0 0 0);
  --ui-sidebar-border: oklch(1.00 0 0);
  --ui-sidebar-ring: oklch(0.70 0.19 23.19);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Space Mono', ui-serif, serif;
  --ui-font-heading: 'DM Sans', ui-sans-serif, sans-serif;
  --ui-font-mono: 'Space Mono', ui-monospace, monospace;
  --ui-shadow-control: 4px 4px 0px 0px oklch(0.00 0 0 / 0.50);
  --ui-shadow-panel:
    4px 4px 0px 0px oklch(0.00 0 0 / 1.00), 4px 4px 6px -1px oklch(0.00 0 0 / 1.00);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
